\title{The Information Cost of a Connectome:\\ Tight Quadratic Bounds on Encoding a Mind}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\begin{abstract}
We study the minimum lossless description length of the \emph{connectome} --- the
wiring diagram of a network of $n$ neurons, modeled as a labeled simple undirected
graph. We prove that this description length is governed exactly by the
pairwise-channel count $\binom{n}{2}=\tfrac{n(n-1)}{2}$: (i) every lossless code
assigns some connectome a codeword of at least $\binom{n}{2}$ bits; (ii) the
canonical adjacency listing meets this bound with equality for every input; and
(iii) no code can shorten all connectomes, so at least one is strictly
incompressible and asymptotically almost every connectome is incompressible. We
connect these facts to Kolmogorov complexity, exhibiting connectomes of complexity
at least $\binom{n}{2}$, and to physics via the Bekenstein bound, obtaining the
necessary condition $\binom{n}{2}\le \frac{2\pi R E}{\hbar c\ln 2}$ for any
physically realized mind of $n$ neurons. The unifying theme is that the information
content of a mind is quadratic in its neuron count because it is carried by
\emph{relationships}, not \emph{units}, and that this cost is exact and robust to
arbitrary compression. We close with four conjectures.
\end{abstract}

\maketitle

\section{Introduction}
The prospect of \emph{mind uploading} raises a question prior to any engineering
concern: what is the minimum number of bits required to represent a mind
losslessly? Any answer depending only on the combinatorial structure of neural
connectivity, and not on the representation technology, has the status of a law.
We isolate the cleanest such structure, the connectome, and prove that its minimum
lossless description length is exactly the number of unordered pairs of neurons,
$\binom{n}{2}$. This number is quadratic in $n$, is achieved by an explicit code,
and cannot be universally beaten. We further show incompressibility is generic and
tie the bound to Kolmogorov complexity and to the Bekenstein bound of physics.

\section{Definitions}
Throughout, $n\in\mathbb{N}$ is the number of neurons and $[n]=\{1,\dots,n\}$ their
labels.

\begin{definition}[Connectome]
A \emph{connectome} on $n$ neurons is a simple undirected graph $G=([n],E)$ with
$E\subseteq\binom{[n]}{2}$; equivalently a symmetric irreflexive adjacency relation
on $[n]$. Let $\Gn$ be the set of all connectomes on $n$ neurons.
\end{definition}

\begin{definition}[Pair count]
The number of unordered pairs of distinct neurons is
$m(n):=\binom{n}{2}=\tfrac{n(n-1)}{2}$. Each pair is an independent binary channel.
\end{definition}

\begin{lemma}[Cardinality]\label{lem:card}
$|\Gn|=2^{m(n)}=2^{\binom{n}{2}}$.
\end{lemma}
\begin{proof}[Proof sketch]
A connectome corresponds bijectively to a function $\binom{[n]}{2}\to\bits$, of
which there are $2^{m(n)}$.
\end{proof}

\begin{definition}[Lossless code]
A \emph{lossless code} on $\Gn$ is an injection $c:\Gn\to\bits^{*}$, with length
$\ell(c,G):=|c(G)|$. Injectivity is losslessness. Write
$L_{\max}(c):=\max_{G}\ell(c,G)$.
\end{definition}

\begin{definition}[Adjacency listing code]
Fix a linear order $p_1,\dots,p_{m(n)}$ of $\binom{[n]}{2}$. The code
$c_{\mathrm{adj}}$ maps $G$ to $b_1\cdots b_{m(n)}$ with $b_i=1$ iff $p_i\in E(G)$.
\end{definition}

\section{The tight quadratic bound}

\begin{lemma}[Short-string count]\label{lem:short}
The number of binary strings of length strictly less than $k$ is
$\sum_{j=0}^{k-1}2^{j}=2^{k}-1$.
\end{lemma}
\begin{proof}[Proof sketch]
There are $2^j$ strings of length $j$; sum the geometric series.
\end{proof}

\begin{theorem}[Quadratic worst-case lower bound]\label{thm:lower}
For every lossless code $c$ on $\Gn$, $\;L_{\max}(c)\ge\binom{n}{2}$.
\end{theorem}
\begin{proof}[Proof sketch]
If every codeword had length $<m(n)$, then by Lemma~\ref{lem:short} the codewords
lie in a set of size $2^{m(n)}-1$, while $|\Gn|=2^{m(n)}$ by
Lemma~\ref{lem:card}. Pigeonhole forces two connectomes to collide, contradicting
injectivity. Hence some codeword has length $\ge m(n)=\binom{n}{2}$.
\end{proof}

\begin{theorem}[Exact attainment]\label{thm:upper}
$c_{\mathrm{adj}}$ is lossless with $\ell(c_{\mathrm{adj}},G)=\binom{n}{2}$ for all
$G$; in particular $L_{\max}(c_{\mathrm{adj}})=\binom{n}{2}$.
\end{theorem}
\begin{proof}[Proof sketch]
The string records the full edge-indicator function, so $E(G)$ is recovered
coordinatewise and the map is injective; every codeword has exactly $m(n)$ bits.
\end{proof}

\begin{corollary}[Minimax description length]
$\displaystyle\min_{c}L_{\max}(c)=\binom{n}{2}$.
\end{corollary}
\begin{proof}[Proof sketch]
Lower bound from Theorem~\ref{thm:lower}, achieved by Theorem~\ref{thm:upper}.
\end{proof}

\section{Incompressibility}

\begin{theorem}[Existence of an incompressible connectome]
For every lossless code $c$ there is $G$ with $\ell(c,G)\ge\binom{n}{2}$.
\end{theorem}
\begin{proof}[Proof sketch]
The pigeonhole overflow element of Theorem~\ref{thm:lower}.
\end{proof}

\begin{theorem}[Budget bound]\label{thm:budget}
Under any lossless code, at most $2^{b+1}-1$ connectomes receive a codeword of
length $\le b$. In particular at most $2^{\binom{n}{2}}-1$ have length
$<\binom{n}{2}$.
\end{theorem}
\begin{proof}[Proof sketch]
There are $2^{b+1}-1$ strings of length $\le b$ (Lemma~\ref{lem:short});
injectivity forbids reuse.
\end{proof}

\begin{theorem}[Generic incompressibility]
Fix a code $c$ and a budget $b(n)=\binom{n}{2}-g(n)$ with $g(n)\to\infty$. The
fraction of connectomes with codeword length $\le b(n)$ is at most
$2^{\,1-g(n)}\to0$.
\end{theorem}
\begin{proof}[Proof sketch]
Divide the count of Theorem~\ref{thm:budget} by $|\Gn|=2^{\binom{n}{2}}$.
\end{proof}

\section{Kolmogorov complexity and the Bekenstein bound}

\begin{definition}[Kolmogorov complexity]
For a fixed universal prefix machine $U$, $K(x)$ is the length of the shortest $p$
with $U(p)=x$. Identify a connectome with its adjacency string.
\end{definition}

\begin{theorem}[Incompressible connectome, Kolmogorov form]\label{thm:kolm}
For every $n$ there is $G\in\Gn$ with $K(G)\ge\binom{n}{2}$.
\end{theorem}
\begin{proof}[Proof sketch]
Programs of length $<m(n)$ number at most $2^{m(n)}-1<2^{m(n)}=|\Gn|$, so some
connectome is output by no shorter program.
\end{proof}

\begin{theorem}[Bekenstein realizability]\label{thm:bek}
If an incompressible connectome on $n$ neurons is instantiated in a spherical
region of radius $R$ and energy $E$, then
$\binom{n}{2}\le\frac{2\pi R E}{\hbar c\ln 2}$.
\end{theorem}
\begin{proof}[Proof sketch]
The instantiation stores at least $K(G)\ge\binom{n}{2}$ bits
(Theorem~\ref{thm:kolm}); the region holds at most $\frac{2\pi RE}{\hbar c\ln2}$
bits by the Bekenstein bound. Chain the inequalities.
\end{proof}

\begin{corollary}[Square-root scaling]
For fixed $R,E$, the largest storable neuron count scales as
$n=O\!\big(\sqrt{2\pi R E/(\hbar c\ln 2)}\big)$.
\end{corollary}
\begin{proof}[Proof sketch]
Solve $\tfrac{n(n-1)}{2}\le B$ for $n$; leading behavior $n=O(\sqrt{B})$.
\end{proof}

\section{Algorithms and numerics}
\emph{Adjacency encode/decode} realizes the optimal code of
Theorem~\ref{thm:upper} in $O(n^2)$ time, emitting exactly $\binom{n}{2}$ bits.
A \emph{bound evaluator} computes $\binom{n}{2}$ and checks
Theorem~\ref{thm:bek}. An \emph{incompressibility auditor} verifies
Theorem~\ref{thm:budget} on small $n$. For $n=2,\dots,8$ the costs $\binom{n}{2}$
are $1,3,6,10,15,21,28$, exhibiting quadratic growth.

\section{Discussion}
Lossless storage of dense wiring cannot be reduced below the pairwise-channel
count by any scheme; the only levers are neuron count and sparsity. Popular
``mostly redundant brain'' arguments are constrained by generic
incompressibility. Corollary in Section 5 injects a conservation law: neuron count
is bounded by the square root of the Bekenstein budget. The quadratic arises
because a connectome encodes relationships ($\binom{n}{2}$), not units ($n$).

\section{Future directions}
\begin{conjecture}[Weighted connectomes]
With $q$ weight levels per synapse, the minimum lossless length is exactly
$\binom{n}{2}\log_2 q$, sharp in the worst case; fidelity is exponentially cheaper
than adding neurons.
\end{conjecture}
\begin{conjecture}[Compressible minds are measure-zero]
For each $b<\binom{n}{2}$, the fraction of connectomes with a length-$\le b$
description tends to $0$; almost all are incompressible below
$\binom{n}{2}-o(\binom{n}{2})$.
\end{conjecture}
\begin{conjecture}[Bounded degree escapes the floor]
With maximum degree $d$, the minimum length is $\Theta(n\,d\log n)$ bits ---
linear in $n$ for fixed $d$ --- and sharp.
\end{conjecture}
\begin{conjecture}[Dynamic Bekenstein bound]
Encoding a mind's trajectory over time $T$ requires at least
$\binom{n}{2}+n\,T$ bits.
\end{conjecture}

\section{Conclusion}
The minimum lossless description length of a connectome on $n$ neurons is exactly
$\binom{n}{2}$ bits: forced by counting, achieved explicitly, robust to
compression, generic, reflected in Kolmogorov complexity, and constrained by the
Bekenstein bound. The information cost of a mind is quadratic because it is the
cost of relationships, not units.

