"""Demo: exact quadratic bit cost of a connectome and its growth signature."""
from math import comb
from typing import List, Tuple

def connectome_bits(n: int) -> int:
    """Minimum worst-case lossless description length in bits: C(n, 2)."""
    return comb(n, 2)

def growth_table(nmax: int) -> List[Tuple[int, int, int]]:
    """Return (n, C(n,2) bits, number of connectomes 2^C(n,2)) for n up to nmax."""
    return [(n, connectome_bits(n), 1 << connectome_bits(n)) for n in range(2, nmax + 1)]

if __name__ == "__main__":
    for n, bits, count in growth_table(10):
        print(f"n={n:>2}  bits=C(n,2)={bits:>3}  connectomes=2^{bits}={count}")
    print("Doubling n from 4->8 raises bits", connectome_bits(4), "->", connectome_bits(8))

"""Demo: Bekenstein-bound realizability and square-root neuron scaling."""
from math import isqrt, log, pi
from typing import Tuple

HBAR = 1.054_571_817e-34
C_LIGHT = 2.997_924_58e8
LN2 = log(2.0)

def bekenstein_bits(radius_m: float, energy_j: float) -> float:
    """Max information (bits) in a sphere of given radius (m) and energy (J)."""
    return 2.0 * pi * radius_m * energy_j / (HBAR * C_LIGHT * LN2)

def max_neurons(budget_bits: float) -> int:
    """Largest n with C(n,2) <= budget; scales like sqrt(budget)."""
    return (1 + isqrt(1 + 8 * int(budget_bits))) // 2

def brain_estimate(radius_m: float, mass_kg: float) -> Tuple[float, int]:
    """Return (Bekenstein capacity in bits, max storable neuron count)."""
    energy = mass_kg * C_LIGHT ** 2
    budget = bekenstein_bits(radius_m, energy)
    return budget, max_neurons(budget)

if __name__ == "__main__":
    budget, n = brain_estimate(0.08, 1.4)
    print(f"Bekenstein capacity ~ {budget:.3e} bits; max neurons ~ {n:.3e}")

