from itertools import combinations
from typing import Iterable, List, Tuple

Edge = Tuple[int, int]

def adjacency_encode(n: int, edges: Iterable[Edge]) -> str:
    """Encode a connectome into an optimal C(n,2)-bit string."""
    present = {tuple(sorted(e)) for e in edges}
    return "".join("1" if p in present else "0" for p in combinations(range(n), 2))

def adjacency_decode(n: int, code: str) -> List[Edge]:
    """Decode a C(n,2)-bit string back into the connectome edge set."""
    order = list(combinations(range(n), 2))
    if len(code) != len(order):
        raise ValueError("code length must equal C(n,2)")
    return [p for p, b in zip(order, code) if b == "1"]

