function AUDIT(connectomes, code, num_pairs):
    seen <- empty map; lengths <- []
    injective <- true
    for g in connectomes:
        w <- code(g)
        if w in seen: injective <- false
        seen[w] <- g; append length(w) to lengths
    for b in 0..num_pairs:
        count <- #{ L in lengths : L <= b }
        cap   <- 2^(b+1) - 1
        record ok <- (count <= cap)
    return report(injective, per-budget ok)

