from typing import Callable, Dict, Hashable, Iterable

def incompressibility_audit(
    connectomes: Iterable[Hashable],
    code: Callable[[Hashable], str],
    num_pairs: int,
) -> Dict[str, object]:
    """Verify the budget bound: at most 2^{b+1}-1 inputs get length <= b.

    Returns a report with, for each length b, the observed count of codewords
    of length <= b and the theoretical maximum 2^{b+1}-1, plus injectivity.
    """
    seen: Dict[str, Hashable] = {}
    lengths = []
    injective = True
    for g in connectomes:
        w = code(g)
        if w in seen:
            injective = False
        seen[w] = g
        lengths.append(len(w))
    report = {"injective": injective, "budget_ok": True, "by_budget": {}}
    for b in range(num_pairs + 1):
        count = sum(1 for L in lengths if L <= b)
        cap = (1 << (b + 1)) - 1
        report["by_budget"][b] = {"count": count, "cap": cap, "ok": count <= cap}
        if count > cap:
            report["budget_ok"] = False
    return report

