from math import isqrt, log, pi

HBAR = 1.054_571_817e-34
C_LIGHT = 2.997_924_58e8
LN2 = log(2.0)

def bekenstein_capacity_bits(radius_m: float, energy_j: float) -> float:
    """Maximum information content (bits) of a sphere (Bekenstein bound)."""
    return 2.0 * pi * radius_m * energy_j / (HBAR * C_LIGHT * LN2)

def realizable(n: int, radius_m: float, energy_j: float) -> bool:
    """True iff the worst-case connectome of n neurons fits the region."""
    from math import comb
    return comb(n, 2) <= bekenstein_capacity_bits(radius_m, energy_j)

def max_realizable_neurons(radius_m: float, energy_j: float) -> int:
    """Largest n with C(n,2) <= Bekenstein capacity; grows like sqrt(cap)."""
    cap = bekenstein_capacity_bits(radius_m, energy_j)
    return (1 + isqrt(1 + 8 * int(cap))) // 2
